self.KB_CONTENT["card:754523"]={"id":"card:754523","ty":"card","sourceId":"754523","title":"『客戶資料建立作業』中的『發票聯數 (MA037)』為何？","ver":"iGP","topic":"稅別碼","keywords":["稅別碼","客戶","發票"],"y":"other","answer":"* 此欄位僅作顯示，取稅別碼設定作業上的發票聯數，欲變更請重新選擇稅別碼。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
