self.KB_CONTENT["card:754659"]={"id":"card:754659","ty":"card","sourceId":"754659","title":"『報價單建立作業』中的『簽核狀態 (TA029)』為何？","ver":"iGP","topic":"報價單","keywords":["報價單","狀態","電子","簽核"],"y":"other","answer":"* 此欄位僅作顯示。簽核狀態碼類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢及N.不執行電子簽核中。其他資料","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
