self.KB_CONTENT["card:757975"]={"id":"card:757975","ty":"card","sourceId":"757975","title":"『庫存單位主檔啟用作業』的作業目的為何？","ver":"iGP","topic":"品號","keywords":["品號","庫存","單位","入庫"],"y":"explain","answer":"可透過此作業啟用庫存單位主檔，以利系統可將目前品號資料中有使用的庫存單位，寫入庫存單位主檔中。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
