self.KB_CONTENT["card:755384"]={"id":"card:755384","ty":"card","sourceId":"755384","title":"『批號資料建立作業』中的『批號 (ME002)』為何？","ver":"iGP","topic":"批號","keywords":["批號","編碼","重複"],"y":"other","answer":"* 不可空白，不可修改，不可重複。* [F3]編碼原則設定查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
