self.KB_CONTENT["card:753148"]={"id":"card:753148","ty":"card","sourceId":"753148","title":"『預算挪用建立作業』中的『總預算金額 (MONEYB)』為何？","ver":"iGP","topic":"預算","keywords":["預算"],"y":"other","answer":"* 此欄位僅作顯示。* 總預算金額(MONEYB)=原始預算金額+追加金額+挪用金額。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
