self.KB_CONTENT["field:752738"]={"id":"field:752738","ty":"field","sourceId":"752738","title":"底稿開立方式","ver":"iGP","topic":"","keywords":[],"job":"分錄性質設定-託外進費用","code":"MB004","answer":"* 付款單開立傳票方式分為1.逐張及2.彙總兩種開立方式。","file":"fields.jsonl"};
